css:
.log-body p { margin: 0 0 0.4em; }
.log-body p:last-child { margin-bottom: 0; }
.log-body ul, .log-body ol { margin: 0.3em 0; padding-left: 1.5em; }
.log-body pre { margin: 0.3em 0; white-space: pre-wrap; font-size: 0.9em; }
.log-mention { font-weight: 600; color: var(--log-accent); }
.log-audio { color: var(--log-muted); font-size: 0.9em; }
.pb { height: 0; }
.cu-text { margin: 0; white-space: pre-wrap; }
.log-node--message { margin: 0 0 calc(var(--log-gap, 0.15) * 1em); }
.nv, .nv-aside, .hd, .tr, .qt, .pro, .cv, .toc, .ip, .cu, .ph, .pf { font-family: var(--log-face); }
.nv { line-height: var(--log-leading, 1.9); text-align: justify; text-indent: calc(var(--log-indent, 2) * 1em); color: var(--log-ink); }
.nv-who { margin-right: 0.4em; text-indent: 0; font-size: 0.72em; font-weight: 600; letter-spacing: 0.14em; color: var(--log-speaker-color, var(--log-accent)); }
.log-merged .nv-who { display: none; }
.nv-p { display: inline; }
.nv-p p { display: inline; margin: 0; }
.nv-p p:not(:last-child)::after { content: ""; display: block; height: 0.35em; }
.nv-p p + p::before { content: "　　"; }
.nv-ic .nv-p p + p::before { content: "　　" var(--log-qopen, "「"); }
.nv-p img { display: block; max-height: calc(var(--log-content-height, 180mm) * 0.45); margin: 0.8em auto; }
.nv-ic .nv-p::before { content: var(--log-qopen, "「"); }
.nv-ic .nv-p::after { content: var(--log-qclose, "」"); }
.log-continued .nv { text-indent: 0; }
.log-continued .nv-p::before { content: none; }
.log-continues .nv-p::after { content: none; }
.log-node--element[data-log-element-type="heading"] + .log-node--message .nv { text-indent: 0; }
.nv-ooc { margin: 0.3em 0 0.6em calc(var(--log-indent, 2) * 1em); padding-left: 0.7em; border-left: 1px solid var(--log-rule); text-align: left; font-family: var(--log-font-family); font-size: 0.76em; line-height: 1.6; color: var(--log-muted); }
.nv-mark { margin-right: 0.5em; letter-spacing: 0.1em; }
.nv-oname { font-weight: 600; }
.nv-oname::after { content: "："; }
.log-merged .nv-mark, .log-merged .nv-oname { display: none; }
.nv-aside { margin: 0.9em 10%; text-align: center; font-size: 0.85em; line-height: 1.7; letter-spacing: 0.04em; color: var(--log-muted); }
.nv-dice::before { content: "◇"; display: block; font-size: 0.75em; color: var(--log-accent); }
.nv-bname { margin-right: 0.6em; font-size: 0.9em; letter-spacing: 0.15em; }
.log-merged .nv-bname { display: none; }
.hd { margin: 2.2em 0 1.4em; text-align: center; font-size: 1.2em; font-weight: 400; letter-spacing: 0.3em; color: var(--log-ink); break-after: avoid; }
.hd::after { content: ""; display: block; width: 2em; margin: 0.7em auto 0; border-top: 1px solid var(--log-accent); }
[data-log-level="1"] .hd { margin-top: 0; padding-top: calc(var(--log-content-height, 180mm) * 0.16); font-size: 1.55em; break-before: page; }
[data-log-level="3"] .hd { margin: 1.6em 0 0.9em; font-size: 1em; letter-spacing: 0.15em; }
[data-log-level="3"] .hd::after { display: none; }
.tr { margin: 1.6em 0; text-align: var(--log-style-align, center); letter-spacing: 0.8em; font-size: 0.9em; color: var(--log-accent); }
.qt { margin: 1.4em 0 1.6em 28%; font-size: 0.9em; line-height: 1.8; text-align: var(--log-style-align, left); color: var(--log-muted); }
.log-style-italic .qt { font-style: italic; }
.pro { margin: 0 0 1.8em; line-height: var(--log-leading, 1.9); text-align: justify; color: var(--log-ink); }
.pro-h { margin: 0 0 1.2em; text-align: center; font-size: 1.15em; font-weight: 400; letter-spacing: 0.5em; color: var(--log-accent); }
.pro-b p { margin: 0; text-indent: calc(var(--log-indent, 2) * 1em); }
.pro-b p:first-child { text-indent: 0; }
.pro-b p:first-child::first-letter { float: left; margin: 0.06em 0.12em 0 0; font-size: 3em; line-height: 0.9; color: var(--log-accent); }
.cv { min-height: calc(var(--log-content-height, 180mm) * 0.92); display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; break-after: page; }
.cv-title { margin: 0; font-size: 2.1em; font-weight: 400; line-height: 1.4; letter-spacing: 0.25em; color: var(--log-ink); }
.cv-rule { width: 3em; margin: 1.2em 0; border-top: 1px solid var(--log-accent); }
.cv-sub { margin: 0; font-size: 0.95em; letter-spacing: 0.3em; color: var(--log-muted); }
.cv-fig { margin: 2.4em 0 0; }
.cv-fig img { max-height: calc(var(--log-content-height, 180mm) * 0.4); }
.ip { margin: 1.4em 0; text-align: center; break-inside: avoid; }
.ip figcaption { margin-top: 0.6em; font-size: 0.82em; letter-spacing: 0.1em; color: var(--log-muted); }
.ip figcaption::before { content: "—— "; }
.toc { padding-top: 12%; break-after: page; }
.toc-h { margin: 0 0 1.6em; text-align: center; font-size: 1.2em; font-weight: 400; letter-spacing: 0.6em; }
.toc .log-toc-item { padding: 0.25em 0; }
.toc .log-toc-text { display: flex; align-items: baseline; }
.toc .log-toc-text::after { content: ""; flex: 1; margin: 0 0.5em; border-bottom: 1px dotted var(--log-rule); }
.cu { margin: 1.4em 8%; padding: 0.8em 0; border-top: 1px solid var(--log-rule); border-bottom: 1px solid var(--log-rule); text-align: center; break-inside: avoid; }
.log-style-accent .cu { border-color: var(--log-accent); }
.cu-title { margin-bottom: 0.4em; letter-spacing: 0.3em; color: var(--log-accent); }
.cu-note { margin: 0.5em 0 0; font-size: 0.82em; color: var(--log-muted); }
.ph { width: 100%; text-align: center; letter-spacing: 0.3em; }
.log-page:nth-child(odd) .ph-title { display: none; }
.log-page:nth-child(even) .ph-sec { display: none; }
.pf { width: 100%; text-align: center; }
.pf-num::before { content: "— "; }
.pf-num::after { content: " —"; }
